{"id": "canvas-preview-frame", "name": "The preview canvas", "summary": "The canvas shows the composition at the playhead, at the project's size, centred in the preview pane.", "page": "canvas/the-canvas", "anchor": "what-the-canvas-shows", "where": "Preview pane"}
{"id": "canvas-caption", "name": "Canvas size and rate caption", "summary": "A small line under the picture states the canvas size and frame rate.", "page": "canvas/the-canvas", "anchor": "the-caption", "where": "Preview pane, below the picture"}
{"id": "canvas-layer-stacking", "name": "Layers stack back to front", "summary": "Tracks stack back to front, so a track higher in the timeline draws in front, and every clip that draws is placed the same way.", "page": "canvas/the-canvas", "anchor": "layers"}
{"id": "canvas-direct-editing", "name": "What you can do on the canvas", "summary": "Select, move, scale, rotate and crop a clip directly on the picture, with the same placement the Picture tab shows as numbers.", "page": "canvas/the-canvas", "anchor": "working-on-the-canvas", "where": "Preview canvas"}
{"id": "canvas-hidden-and-locked", "name": "Hidden and locked tracks on the canvas", "summary": "Clips on hidden tracks are not drawn and can't be clicked; clips on locked tracks are drawn but can't be selected or moved on the canvas.", "page": "canvas/the-canvas", "anchor": "hidden-and-locked-tracks", "where": "Preview canvas"}
{"id": "canvas-modes", "name": "Canvas modes", "summary": "Canvas tools that wait for a click or a drag show a crosshair and a hint pill, only one can be armed at a time, and Esc leaves it.", "page": "canvas/the-canvas", "anchor": "canvas-modes", "where": "Preview canvas", "keys": "Esc"}
{"id": "canvas-zoom-popup", "name": "Canvas zoom popup", "summary": "A toolbar popup sets how large the picture appears in the preview.", "page": "canvas/zoom-and-pan", "anchor": "the-zoom-popup", "where": "Toolbar view cluster: zoom popup"}
{"id": "canvas-zoom-commands", "name": "Zoom In, Zoom Out and Zoom to Fit", "summary": "View menu commands step the preview through the same four stops, or go straight back to Fit.", "page": "canvas/zoom-and-pan", "anchor": "view-menu-commands", "where": "View ▸ Zoom In", "keys": "⌘+"}
{"id": "canvas-zoom-gestures", "name": "Pinch and scroll to zoom", "summary": "A trackpad pinch, or scrolling with ⌥ or ⌘ held, steps through the zoom stops.", "page": "canvas/zoom-and-pan", "anchor": "pinch-and-scroll", "where": "Pinch over the preview", "keys": "⌥-scroll"}
{"id": "canvas-pan", "name": "Pan a zoomed canvas", "summary": "When the zoomed canvas is bigger than the pane, scroll or hold Space and drag to pan it.", "page": "canvas/zoom-and-pan", "anchor": "panning", "where": "Scroll over the preview", "keys": "Space-drag"}
{"id": "canvas-space-key", "name": "Space on the canvas", "summary": "With the canvas focused, a quick Space tap still plays and pauses, and holding Space to drag pans.", "page": "canvas/zoom-and-pan", "anchor": "space-on-the-canvas", "where": "Space on the preview canvas", "keys": "Space"}
{"id": "canvas-click-select", "name": "Click to select a layer", "summary": "Clicking the picture selects the front-most visible clip under the pointer at the playhead.", "page": "canvas/select-on-canvas", "anchor": "click-a-layer", "where": "Click on the preview canvas"}
{"id": "canvas-shift-click", "name": "⇧-click on the canvas", "summary": "⇧-click adds a clip to the selection or removes it.", "page": "canvas/select-on-canvas", "anchor": "shift-click", "where": "⇧-click on the preview canvas", "keys": "⇧-click"}
{"id": "canvas-click-void", "name": "Click empty canvas to deselect", "summary": "Clicking empty canvas clears the selection and leaves crop mode.", "page": "canvas/select-on-canvas", "anchor": "clear-the-selection", "where": "Click empty canvas"}
{"id": "canvas-selection-frame", "name": "The selection frame and handles", "summary": "Every selected clip gets an outline, and the front-most selected clip also gets eight square handles and a round rotation grip.", "page": "canvas/select-on-canvas", "anchor": "the-selection-frame", "where": "Preview canvas"}
{"id": "canvas-select-matte-clips", "name": "Selecting matte clips", "summary": "A clip on a matte track can be selected and dragged inside its own box even though it draws nothing there.", "page": "canvas/select-on-canvas", "anchor": "matte-clips", "where": "Click on the preview canvas"}
{"id": "canvas-move", "name": "Drag to move", "summary": "Drag inside a clip's box to move it, and every selected clip moves by the same amount.", "page": "canvas/move-scale-rotate", "anchor": "move", "where": "Drag a clip in the preview"}
{"id": "canvas-nudge", "name": "Nudge with the arrow keys", "summary": "With the canvas focused, the arrow keys move the selected clips one canvas pixel, or ten with ⇧.", "page": "canvas/move-scale-rotate", "anchor": "nudge", "where": "← → ↑ ↓ with the canvas focused", "keys": "←"}
{"id": "canvas-scale-handles", "name": "Scale with the eight handles", "summary": "Drag a corner or edge handle to scale the clip, with the opposite handle pinned in place.", "page": "canvas/move-scale-rotate", "anchor": "scale", "where": "Drag a square handle in the preview"}
{"id": "canvas-scale-about-centre", "name": "Scale about the centre", "summary": "Hold ⌥ while scaling to keep the clip's centre still instead of the opposite handle.", "page": "canvas/move-scale-rotate", "anchor": "scale-about-the-centre", "where": "⌥ during a handle drag", "keys": "⌥-drag"}
{"id": "canvas-rotate", "name": "Rotate with the grip", "summary": "Drag the round grip above the top edge to rotate the clip about its centre.", "page": "canvas/move-scale-rotate", "anchor": "rotate", "where": "Drag the rotation grip"}
{"id": "canvas-rotate-snap", "name": "Snap the angle", "summary": "Hold ⇧ while rotating to snap the angle to 15° steps.", "page": "canvas/move-scale-rotate", "anchor": "snap-the-angle", "where": "⇧ during a rotation drag", "keys": "⇧-drag"}
{"id": "canvas-cancel-drag", "name": "Cancel a drag", "summary": "Press Esc during a canvas drag to put everything back, with no undo step.", "page": "canvas/move-scale-rotate", "anchor": "cancel-a-drag", "where": "Esc during a canvas drag", "keys": "Esc"}
{"id": "canvas-fixed-pivot", "name": "The fixed pivot", "summary": "Rotation, the Scale field and a ⌥ scale drag all pivot on the centre of the clip's uncropped picture.", "page": "canvas/move-scale-rotate", "anchor": "the-pivot"}
{"id": "canvas-undo-per-drag", "name": "One undo step per drag", "summary": "Each canvas drag is one undo step, and a click that moves nothing adds no step.", "page": "canvas/move-scale-rotate", "anchor": "one-undo-step-per-drag"}
{"id": "canvas-snap-targets", "name": "What a move snaps to", "summary": "While you drag a clip to move it, its box snaps to the canvas and to other visible layers.", "page": "canvas/canvas-snapping", "anchor": "what-snaps", "where": "Drag a clip with snapping on"}
{"id": "canvas-snap-guides", "name": "Snap guide lines", "summary": "A guide line is drawn across the canvas on each axis that snapped.", "page": "canvas/canvas-snapping", "anchor": "guide-lines"}
{"id": "canvas-snap-suspend", "name": "Suspend snapping for one drag", "summary": "Hold ⌘ during a drag to stop snapping for that drag.", "page": "canvas/canvas-snapping", "anchor": "suspend-for-one-drag", "where": "⌘ during a drag", "keys": "⌘-drag"}
{"id": "safe-areas", "name": "Safe area guides", "summary": "Two guide frames over the picture mark the 90 % title-safe and 80 % action-safe areas.", "page": "canvas/safe-areas", "anchor": "safe-area-guides", "where": "View ▸ Safe Areas"}
{"id": "crop-section", "name": "The Crop section", "summary": "Type how many source pixels to cut from each edge of a video, image or still clip.", "page": "canvas/crop", "anchor": "the-crop-section", "where": "Inspector ▸ Clip ▸ Picture ▸ Crop: Left, Top, Right, Bottom"}
{"id": "crop-mode", "name": "Crop mode", "summary": "Press C, double-click a clip or use Crop on Canvas to crop the selected clip with handles on the canvas.", "page": "canvas/crop", "anchor": "crop-mode", "where": "C", "keys": "C"}
{"id": "crop-handles", "name": "Crop handles", "summary": "In crop mode the eight handles trim the clip's edges, and what is being cut away shows as a dim ghost.", "page": "canvas/crop", "anchor": "crop-handles", "where": "Drag a crop handle in crop mode"}
{"id": "crop-leave", "name": "Leaving crop mode", "summary": "Return, keypad Enter, Esc, C or a click on empty canvas leave crop mode.", "page": "canvas/crop", "anchor": "leaving-crop-mode", "where": "Return", "keys": "↩"}
{"id": "crop-in-place", "name": "A crop removes edges in place", "summary": "A crop never shifts the picture, and its amounts stay correct when you scale the clip later.", "page": "canvas/crop", "anchor": "how-a-crop-works"}
{"id": "picture-tab-sections", "name": "The Picture tab's sections", "summary": "The Clip tab's Picture sub-tab holds a clip's placement and picture effects, and which sections show depends on the selection.", "page": "canvas/picture-tab", "anchor": "sections-in-order", "where": "Inspector ▸ Clip ▸ Picture"}
{"id": "picture-tab-behaviour", "name": "How the sections behave", "summary": "Sections fold, show a summary while closed, and edit every selected clip at once.", "page": "canvas/picture-tab", "anchor": "how-sections-behave", "where": "Inspector ▸ Clip ▸ Picture"}
{"id": "picture-tab-agents", "name": "Picture settings for agents", "summary": "set_video changes clips' placement, look and effects by merging a patch into each clip's video properties.", "page": "canvas/picture-tab", "anchor": "with-an-agent"}
{"id": "transform-section", "name": "The Transform section", "summary": "Transform holds a clip's scale, position, rotation, opacity and blend, for every clip that draws.", "page": "canvas/transform", "anchor": "the-transform-section", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform"}
{"id": "transform-scale", "name": "Scale", "summary": "Sets the clip's size as a percentage, where 100 % is its native pixels.", "page": "canvas/transform", "anchor": "scale", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform ▸ Scale"}
{"id": "transform-position", "name": "Position X and Y", "summary": "Places the clip in canvas pixels, measured from the canvas centre.", "page": "canvas/transform", "anchor": "position", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform ▸ Position X, Position Y"}
{"id": "transform-rotation", "name": "Rotation", "summary": "Turns the clip in degrees about its centre; a positive angle turns clockwise on screen.", "page": "canvas/transform", "anchor": "rotation", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform ▸ Rotation"}
{"id": "transform-opacity", "name": "Opacity", "summary": "Sets how see-through the clip is.", "page": "canvas/transform", "anchor": "opacity", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform ▸ Opacity"}
{"id": "transform-fit", "name": "Fit to Canvas", "summary": "Scales each selected clip so its whole picture fits the canvas, and centres it.", "page": "canvas/transform", "anchor": "fit-and-fill", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform ▸ Fit to Canvas"}
{"id": "transform-fill", "name": "Fill Canvas", "summary": "Scales each selected clip until it covers the whole canvas, and centres it.", "page": "canvas/transform", "anchor": "fit-and-fill", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform ▸ Fill Canvas"}
{"id": "transform-reset", "name": "Reset Transform", "summary": "Puts position, scale, rotation, opacity, blend and motion blur back to their defaults in one step.", "page": "canvas/transform", "anchor": "reset", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform ▸ Reset"}
{"id": "transform-stretching", "name": "Stretching only on shapes and text", "summary": "Scale is uniform for pictures: only shapes (box width and height) and text (wrap width) can change on one axis.", "page": "canvas/transform", "anchor": "no-stretching"}
{"id": "blend-popup", "name": "The Blend popup", "summary": "Chooses how a layer combines with what is under it.", "page": "canvas/blend-modes", "anchor": "the-blend-popup", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform ▸ Blend"}
{"id": "blend-normal", "name": "Normal blend mode", "summary": "Draws over what is underneath.", "page": "canvas/blend-modes", "anchor": "the-eight-modes", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform ▸ Blend ▸ Normal"}
{"id": "blend-multiply", "name": "Multiply blend mode", "summary": "Darkens by multiplying with what is underneath.", "page": "canvas/blend-modes", "anchor": "the-eight-modes", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform ▸ Blend ▸ Multiply"}
{"id": "blend-screen", "name": "Screen blend mode", "summary": "Lightens, the inverse of multiply.", "page": "canvas/blend-modes", "anchor": "the-eight-modes", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform ▸ Blend ▸ Screen"}
{"id": "blend-add", "name": "Add blend mode", "summary": "Adds the colours together.", "page": "canvas/blend-modes", "anchor": "the-eight-modes", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform ▸ Blend ▸ Add"}
{"id": "blend-overlay", "name": "Overlay blend mode", "summary": "Multiplies the darks and screens the lights.", "page": "canvas/blend-modes", "anchor": "the-eight-modes", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform ▸ Blend ▸ Overlay"}
{"id": "blend-darken", "name": "Darken blend mode", "summary": "Keeps the darker of the two colours.", "page": "canvas/blend-modes", "anchor": "the-eight-modes", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform ▸ Blend ▸ Darken"}
{"id": "blend-lighten", "name": "Lighten blend mode", "summary": "Keeps the lighter of the two colours.", "page": "canvas/blend-modes", "anchor": "the-eight-modes", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform ▸ Blend ▸ Lighten"}
{"id": "blend-difference", "name": "Difference blend mode", "summary": "Gives the absolute difference of the two colours.", "page": "canvas/blend-modes", "anchor": "the-eight-modes", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform ▸ Blend ▸ Difference"}
{"id": "blend-nothing-behind", "name": "The nothing-behind note", "summary": "The Transform section warns when a blend has nothing under it to work against.", "page": "canvas/blend-modes", "anchor": "nothing-behind", "where": "Inspector ▸ Clip ▸ Picture ▸ Transform"}
{"id": "blend-during-transition", "name": "Blend during a transition", "summary": "A layer draws as Normal for as long as it is in a transition, whatever blend mode it has.", "page": "canvas/blend-modes", "anchor": "during-a-transition"}
{"id": "corner-radius", "name": "Corner Radius", "summary": "Rounds the corners of a video, image or still clip's cropped picture.", "page": "canvas/corner-radius", "anchor": "round-the-corners", "where": "Inspector ▸ Clip ▸ Picture ▸ Corner Radius ▸ Radius"}
{"id": "background-new-track", "name": "A background gets its own track", "summary": "Each background command puts one clip on a new back-most track and selects it.", "page": "canvas/backgrounds", "anchor": "a-new-back-most-track", "where": "Clip menu"}
{"id": "background-solid", "name": "Add Background: Solid Color", "summary": "Puts a canvas-sized white rectangle named \"Background\" behind everything, starting at 0 and as long as the timeline.", "page": "canvas/backgrounds", "anchor": "solid-color", "where": "Clip ▸ Add Background ▸ Solid Color"}
{"id": "background-image", "name": "Add Background: Image", "summary": "Puts a picture you choose behind everything, scaled to fill the canvas and as long as the timeline.", "page": "canvas/backgrounds", "anchor": "image", "where": "Clip ▸ Add Background ▸ Image…"}
{"id": "background-blurred", "name": "Add Blurred Background", "summary": "Puts a muted, blurred, canvas-filling copy of the selected clip behind it, playing exactly the same frames: the usual backdrop for a screen recording or a vertical video.", "page": "canvas/backgrounds", "anchor": "blurred-background", "where": "Clip ▸ Add Blurred Background"}
{"id": "matte-tracks", "name": "Matte tracks", "summary": "A matte track cuts the track directly behind it: its clips are never drawn, and what they show decides where the track behind can be seen.", "page": "canvas/matte-tracks", "anchor": "what-a-matte-does", "where": "Track ▸ Matte"}
{"id": "matte-menu", "name": "Setting a matte", "summary": "Set the mode from Track ▸ Matte for the current track, or from a track's context menu for that track.", "page": "canvas/matte-tracks", "anchor": "setting-a-matte", "where": "Track ▸ Matte ▸ Off, Alpha, Inverted Alpha, Luma, Inverted Luma"}
{"id": "matte-off", "name": "Matte mode: Off", "summary": "An ordinary track, which is every track's default.", "page": "canvas/matte-tracks", "anchor": "the-modes", "where": "Track ▸ Matte ▸ Off"}
{"id": "matte-mode-alpha", "name": "Matte mode: Alpha", "summary": "The track behind shows where the matte clip is opaque.", "page": "canvas/matte-tracks", "anchor": "the-modes", "where": "Track ▸ Matte ▸ Alpha"}
{"id": "matte-mode-inverted-alpha", "name": "Matte mode: Inverted Alpha", "summary": "The track behind shows where the matte clip is transparent.", "page": "canvas/matte-tracks", "anchor": "the-modes", "where": "Track ▸ Matte ▸ Inverted Alpha"}
{"id": "matte-mode-luma", "name": "Matte mode: Luma", "summary": "The track behind shows where the matte clip is bright.", "page": "canvas/matte-tracks", "anchor": "the-modes", "where": "Track ▸ Matte ▸ Luma"}
{"id": "matte-mode-inverted-luma", "name": "Matte mode: Inverted Luma", "summary": "The track behind shows where the matte clip is dark.", "page": "canvas/matte-tracks", "anchor": "the-modes", "where": "Track ▸ Matte ▸ Inverted Luma"}
{"id": "matte-gaps", "name": "Gaps in a matte track", "summary": "Where the matte track has no clip, the track behind shows uncut.", "page": "canvas/matte-tracks", "anchor": "gaps"}
{"id": "matte-temporarily-off", "name": "Turning a cut off for a while", "summary": "Hiding the matte track, or turning off a matte clip's video, turns the cut off and shows the track behind whole.", "page": "canvas/matte-tracks", "anchor": "turning-a-matte-off"}
{"id": "matte-no-target", "name": "A matte with nothing to cut", "summary": "A matte with no target cuts nothing and still draws nothing.", "page": "canvas/matte-tracks", "anchor": "nothing-to-cut"}
{"id": "matte-shaping", "name": "What shapes a matte", "summary": "A matte clip's position, scale, rotation, crop, opacity, colour, filters, actions and transitions all shape the matte, so a moving title can wipe footage on.", "page": "canvas/matte-tracks", "anchor": "matte-properties"}
{"id": "matte-ignored", "name": "What a matte ignores", "summary": "A matte clip's blend mode, drop shadow and reflection have no effect, but they are kept and apply again when the track stops being a matte.", "page": "canvas/matte-tracks", "anchor": "matte-properties"}
{"id": "matte-sound", "name": "A matte clip's sound", "summary": "A matte clip's sound still plays.", "page": "canvas/matte-tracks", "anchor": "sound"}
{"id": "matte-adjustment-clip", "name": "Adjustment clips and mattes", "summary": "On a track cut by a matte, an adjustment clip grades only inside the matte; on a matte track it does nothing.", "page": "canvas/matte-tracks", "anchor": "adjustment-clips", "where": "Timeline"}
{"id": "matte-note", "name": "The matte note on the Clip tab", "summary": "With the selection on a matte track, every Clip sub-tab shows a note under its strip saying what the matte does, and every control stays live.", "page": "canvas/matte-tracks", "anchor": "the-note-on-the-clip-tab", "where": "Inspector ▸ Clip, under the sub-tabs"}
{"id": "matte-chrome", "name": "How a matte track looks", "summary": "A matte track's header carries a tag, its clips draw at half opacity with dashed outlines, and a bracket joins it to the track it cuts.", "page": "canvas/matte-tracks", "anchor": "on-the-timeline", "where": "Timeline track header"}
{"id": "matte-inside-nest", "name": "Mattes inside a nest", "summary": "A matte track works inside a nest just as it does on the timeline, and a clip in a nest that sits on a matte track becomes a matte at the first matte track found going outward.", "page": "canvas/mattes-in-nests", "anchor": "inside-a-nest"}
{"id": "matte-nest", "name": "Nesting a matte", "summary": "Nest keeps a track's matte only when the track it cuts is nested with it.", "page": "canvas/mattes-in-nests", "anchor": "nest", "where": "Clip ▸ Nest", "keys": "⌘G"}
{"id": "matte-unnest", "name": "Un-nesting a matte", "summary": "Un-nest lines the nest's front-most non-matte track up with the nest clip's track, so the picture comes back as it was.", "page": "canvas/mattes-in-nests", "anchor": "un-nest", "where": "Clip ▸ Un-nest", "keys": "⇧⌘G"}
{"id": "matte-transitions", "name": "Transitions across matted tracks", "summary": "Mattes work through transitions, and a dissolve or zoom with a nested half mixes its two halves exactly, matte or not.", "page": "canvas/mattes-in-nests", "anchor": "transitions", "where": "Timeline"}

